-- US MD/MBBS (4th Year) clinical case blocks - Geriatrics: Sensory changes — presbycusis, presbyopia, functional consequences - Part 4 (301-350)
BEGIN;

DO $$
DECLARE
    v_topic_id UUID;
BEGIN
    SELECT id INTO v_topic_id FROM topics WHERE slug = 'geri-sensory-changes' LIMIT 1;
    IF v_topic_id IS NULL THEN
        RAISE EXCEPTION 'Topic geri-sensory-changes not found.';
    END IF;

    INSERT INTO mcqs (topic_id, question, options, correct_index, explanation) VALUES
    (v_topic_id, 'A 91-year-old female named Gladys with mild cognitive impairment (MCI) and severe untreated presbycusis is evaluated for progressive memory loss. According to recent epidemiological evidence (such as the *Lancet* Commission on Dementia), which of the following is the most accurate statement regarding the relationship between hearing loss and dementia?', '["Hearing aids increase the rate of cognitive decline by over-stimulating the temporal lobes and causing neuronal exhaustion", "Midlife and late-life hearing loss is identified as the single largest modifiable risk factor for dementia; untreated hearing loss is associated with accelerated cognitive decline and brain atrophy, and treating it with hearing aids may delay or reduce cognitive decline", "There is no association between sensory deficits and cognitive function; they are entirely independent processes", "Hearing loss is a late symptom of dementia and has no causative or accelerating relationship with cognitive decline", "Dementia only occurs in individuals with conductive hearing loss; sensorineural loss is protective against Alzheimer''s disease"]'::jsonb, 1, 'The **2020 Lancet Commission on Dementia Prevention, Intervention, and Care** identified **hearing loss as the single largest modifiable risk factor for dementia**, accounting for approximately 8% of all dementia cases. Pathophysiological hypotheses include: (1) **Cognitive load hypothesis** (auditory processing exhausts cognitive reserve, leaving fewer resources for memory and executive function), (2) **Sensory deprivation hypothesis** (lack of input leads to direct temporal lobe atrophy), and (3) **Social isolation hypothesis** (hearing loss causes isolation, which accelerates decline). Large trials (e.g., the ACHIEVE study) indicate that treating hearing loss with hearing aids significantly reduces cognitive decline in older adults at increased risk. (Ref: Lancet Commission 2020; ACHIEVE Trial, Lancet 2023; Hazzard''s Ch. 45)'),
